create table if not exists public.hr_shift_attendance (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,store_id uuid not null,operator_id uuid not null,operator_name text not null,event_type text not null check(event_type in ('ENTRADA_PIN','SAIDA_TURNO','FALTA')),event_at timestamptz not null default now(),notes text,created_at timestamptz not null default now());
alter table public.hr_shift_attendance enable row level security;
create policy hr_shift_attendance_select on public.hr_shift_attendance for select to authenticated using(private.has_store_access(store_id));
create or replace function public.record_operator_attendance(p_store_id uuid,p_operator_id uuid,p_event_type text,p_notes text default null) returns uuid language plpgsql security definer set search_path='public','private','auth' as $$ declare v_tenant uuid; v_name text; v_id uuid; begin if auth.uid() is null or not private.has_store_access(p_store_id) then raise exception 'store access denied'; end if; if p_event_type not in ('ENTRADA_PIN','SAIDA_TURNO','FALTA') then raise exception 'invalid attendance event'; end if; select tenant_id into v_tenant from public.stores where id=p_store_id and active=true; select name into v_name from public.operators where id=p_operator_id and tenant_id=v_tenant and store_id=p_store_id and active=true; if v_name is null then raise exception 'operator not found'; end if; insert into public.hr_shift_attendance(tenant_id,store_id,operator_id,operator_name,event_type,notes) values(v_tenant,p_store_id,p_operator_id,v_name,p_event_type,nullif(trim(coalesce(p_notes,'')),'')) returning id into v_id; return v_id; end $$;
grant execute on function public.record_operator_attendance(uuid,uuid,text,text) to authenticated;